-- orders: key stats
SELECT COUNT(*) AS cnt, MIN("order_id") AS lo, MAX("order_id") AS hi FROM "app"."orders"

-- orders: range chunk fingerprints
SELECT b, COUNT(*) AS cnt, SUM(h) AS hsum FROM (SELECT div(("order_id" - @lo)::numeric, @w)::bigint AS b, ('x' || substr(md5(CASE WHEN "order_id" IS NULL THEN '~' ELSE octet_length(trim_scale("order_id"::numeric)::text)::text || ':' || trim_scale("order_id"::numeric)::text END || CASE WHEN NULLIF(rtrim("customer_code"::text, ' '), '') IS NULL THEN '~' ELSE octet_length(NULLIF(rtrim("customer_code"::text, ' '), ''))::text || ':' || NULLIF(rtrim("customer_code"::text, ' '), '') END || CASE WHEN "status" IS NULL THEN '~' ELSE octet_length("status"::text)::text || ':' || "status"::text END || CASE WHEN "note" IS NULL THEN '~' ELSE octet_length("note"::text)::text || ':' || "note"::text END || CASE WHEN "amount" IS NULL THEN '~' ELSE octet_length(trim_scale("amount"::numeric)::text)::text || ':' || trim_scale("amount"::numeric)::text END || CASE WHEN "discount_rate" IS NULL THEN '~' ELSE octet_length(trim_scale("discount_rate"::numeric)::text)::text || ':' || trim_scale("discount_rate"::numeric)::text END || CASE WHEN "created_on" IS NULL THEN '~' ELSE octet_length(to_char("created_on", 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_trunc('second', "created_on") <> "created_on" THEN to_char("created_on", '.US') ELSE '' END)::text || ':' || to_char("created_on", 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_trunc('second', "created_on") <> "created_on" THEN to_char("created_on", '.US') ELSE '' END END || CASE WHEN "shipped_at" IS NULL THEN '~' ELSE '26' || ':' || to_char("shipped_at", 'YYYY-MM-DD"T"HH24:MI:SS.US') END || CASE WHEN "updated_at" IS NULL THEN '~' ELSE '27' || ':' || to_char(("updated_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END), 1, 15))::bit(60)::bigint AS h FROM "app"."orders" WHERE "order_id" BETWEEN @lo AND @hi) s GROUP BY b ORDER BY b

-- orders: leaf row digests (2 ranges)
SELECT "order_id" AS k, md5(CASE WHEN "order_id" IS NULL THEN '~' ELSE octet_length(trim_scale("order_id"::numeric)::text)::text || ':' || trim_scale("order_id"::numeric)::text END || CASE WHEN NULLIF(rtrim("customer_code"::text, ' '), '') IS NULL THEN '~' ELSE octet_length(NULLIF(rtrim("customer_code"::text, ' '), ''))::text || ':' || NULLIF(rtrim("customer_code"::text, ' '), '') END || CASE WHEN "status" IS NULL THEN '~' ELSE octet_length("status"::text)::text || ':' || "status"::text END || CASE WHEN "note" IS NULL THEN '~' ELSE octet_length("note"::text)::text || ':' || "note"::text END || CASE WHEN "amount" IS NULL THEN '~' ELSE octet_length(trim_scale("amount"::numeric)::text)::text || ':' || trim_scale("amount"::numeric)::text END || CASE WHEN "discount_rate" IS NULL THEN '~' ELSE octet_length(trim_scale("discount_rate"::numeric)::text)::text || ':' || trim_scale("discount_rate"::numeric)::text END || CASE WHEN "created_on" IS NULL THEN '~' ELSE octet_length(to_char("created_on", 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_trunc('second', "created_on") <> "created_on" THEN to_char("created_on", '.US') ELSE '' END)::text || ':' || to_char("created_on", 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_trunc('second', "created_on") <> "created_on" THEN to_char("created_on", '.US') ELSE '' END END || CASE WHEN "shipped_at" IS NULL THEN '~' ELSE '26' || ':' || to_char("shipped_at", 'YYYY-MM-DD"T"HH24:MI:SS.US') END || CASE WHEN "updated_at" IS NULL THEN '~' ELSE '27' || ':' || to_char(("updated_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END) AS d FROM "app"."orders" WHERE "order_id" BETWEEN @lo0 AND @hi0 OR "order_id" BETWEEN @lo1 AND @hi1

-- orders: encoded fields by key (2 keys)
SELECT "order_id" AS k, CASE WHEN "order_id" IS NULL THEN '~' ELSE octet_length(trim_scale("order_id"::numeric)::text)::text || ':' || trim_scale("order_id"::numeric)::text END AS c0, CASE WHEN NULLIF(rtrim("customer_code"::text, ' '), '') IS NULL THEN '~' ELSE octet_length(NULLIF(rtrim("customer_code"::text, ' '), ''))::text || ':' || NULLIF(rtrim("customer_code"::text, ' '), '') END AS c1, CASE WHEN "status" IS NULL THEN '~' ELSE octet_length("status"::text)::text || ':' || "status"::text END AS c2, CASE WHEN "note" IS NULL THEN '~' ELSE octet_length("note"::text)::text || ':' || "note"::text END AS c3, CASE WHEN "amount" IS NULL THEN '~' ELSE octet_length(trim_scale("amount"::numeric)::text)::text || ':' || trim_scale("amount"::numeric)::text END AS c4, CASE WHEN "discount_rate" IS NULL THEN '~' ELSE octet_length(trim_scale("discount_rate"::numeric)::text)::text || ':' || trim_scale("discount_rate"::numeric)::text END AS c5, CASE WHEN "created_on" IS NULL THEN '~' ELSE octet_length(to_char("created_on", 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_trunc('second', "created_on") <> "created_on" THEN to_char("created_on", '.US') ELSE '' END)::text || ':' || to_char("created_on", 'YYYY-MM-DD"T"HH24:MI:SS') || CASE WHEN date_trunc('second', "created_on") <> "created_on" THEN to_char("created_on", '.US') ELSE '' END END AS c6, CASE WHEN "shipped_at" IS NULL THEN '~' ELSE '26' || ':' || to_char("shipped_at", 'YYYY-MM-DD"T"HH24:MI:SS.US') END AS c7, CASE WHEN "updated_at" IS NULL THEN '~' ELSE '27' || ':' || to_char(("updated_at" AT TIME ZONE 'UTC'), 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END AS c8 FROM "app"."orders" WHERE "order_id" IN (@k0, @k1)

-- order_documents: bucket fingerprints, SHA-256
SELECT b, COUNT(*) AS cnt, SUM(h) AS hsum FROM (SELECT mod(('x' || substr(md5(CASE WHEN "order_id" IS NULL THEN '~' ELSE octet_length(trim_scale("order_id"::numeric)::text)::text || ':' || trim_scale("order_id"::numeric)::text END || CASE WHEN "doc_no" IS NULL THEN '~' ELSE octet_length(trim_scale("doc_no"::numeric)::text)::text || ':' || trim_scale("doc_no"::numeric)::text END), 1, 8))::bit(32)::bigint, @n) AS b, ('x' || substr(encode(sha256(convert_to(CASE WHEN "order_id" IS NULL THEN '~' ELSE octet_length(trim_scale("order_id"::numeric)::text)::text || ':' || trim_scale("order_id"::numeric)::text END || CASE WHEN "doc_no" IS NULL THEN '~' ELSE octet_length(trim_scale("doc_no"::numeric)::text)::text || ':' || trim_scale("doc_no"::numeric)::text END || CASE WHEN "body" IS NULL THEN '~' ELSE '64:' || encode(sha256(convert_to("body"::text, 'UTF8')), 'hex') END || CASE WHEN "created_at" IS NULL THEN '~' ELSE '26' || ':' || to_char("created_at", 'YYYY-MM-DD"T"HH24:MI:SS.US') END, 'UTF8')), 'hex'), 1, 15))::bit(60)::bigint AS h FROM "app"."order_documents") s GROUP BY b ORDER BY b

-- order_documents: bucket leaf (1 bucket), empty strings as NULL
SELECT CASE WHEN "order_id" IS NULL THEN '~' ELSE octet_length(trim_scale("order_id"::numeric)::text)::text || ':' || trim_scale("order_id"::numeric)::text END || CASE WHEN "doc_no" IS NULL THEN '~' ELSE octet_length(trim_scale("doc_no"::numeric)::text)::text || ':' || trim_scale("doc_no"::numeric)::text END AS k, md5(CASE WHEN "order_id" IS NULL THEN '~' ELSE octet_length(trim_scale("order_id"::numeric)::text)::text || ':' || trim_scale("order_id"::numeric)::text END || CASE WHEN "doc_no" IS NULL THEN '~' ELSE octet_length(trim_scale("doc_no"::numeric)::text)::text || ':' || trim_scale("doc_no"::numeric)::text END || CASE WHEN ("body" IS NULL OR "body"::text = '') THEN '~' ELSE '32:' || md5("body"::text) END || CASE WHEN "created_at" IS NULL THEN '~' ELSE '26' || ':' || to_char("created_at", 'YYYY-MM-DD"T"HH24:MI:SS.US') END) AS d FROM "app"."order_documents" WHERE mod(('x' || substr(md5(CASE WHEN "order_id" IS NULL THEN '~' ELSE octet_length(trim_scale("order_id"::numeric)::text)::text || ':' || trim_scale("order_id"::numeric)::text END || CASE WHEN "doc_no" IS NULL THEN '~' ELSE octet_length(trim_scale("doc_no"::numeric)::text)::text || ':' || trim_scale("doc_no"::numeric)::text END), 1, 8))::bit(32)::bigint, @n) IN (@b0)

-- customers: client-side raw rows
SELECT "customer_code", "full_name", "birth_date", "segment" FROM "app"."customers"
